<dialog id="google-dialog" class="record-dialog import-dialog google-dialog" aria-labelledby="google-title">
    <div class="dialog-heading"><h2 id="google-title">Google Sheets</h2><button type="button" id="google-close" class="button button-quiet button-icon" aria-label="Tutup Google Sheets"><?= $icon('delete') ?></button></div>
    <div class="import-dialog-body form-stack">
        <div id="google-new-source" class="form-stack"><div class="settings-grid"><label>Tautan spreadsheet<input id="google-url" type="url" placeholder="https://docs.google.com/spreadsheets/d/…"></label><label>Baris header<input id="google-header" type="number" min="1" max="1048575" step="1" value="1"></label></div><button type="button" id="google-prepare" class="button button-secondary">Siapkan konektor</button></div>
        <div id="google-setup" class="form-stack" hidden>
            <details id="google-instructions" class="source-instructions"><summary>Pengaturan sekali pada spreadsheet</summary><ol><li>Buka spreadsheet → <strong>Ekstensi → Apps Script</strong>. Tempel kode konektor.</li><li>Jalankan <strong>pasangDoorprize</strong>, lalu berikan izin.</li><li>Pilih <strong>Deploy → New deployment → Web app</strong>. Jalankan sebagai <strong>Me</strong>, akses <strong>Anyone</strong>.</li><li>Tempel URL aplikasi web di bawah. Spreadsheet tetap privat; konektor memeriksa kunci aplikasi.</li></ol><div class="flex flex-wrap gap-2"><button type="button" id="google-copy" class="button button-secondary">Salin kode</button><button type="button" id="google-download" class="button button-quiet">Unduh .gs</button></div><p class="field-hint">Kolom ID dan catatan konektor tersembunyi dibuat untuk melacak perubahan. Jangan dihapus; sortir seluruh baris.</p></details>
            <label>URL aplikasi web<input id="google-endpoint" type="url" placeholder="https://script.google.com/macros/s/…/exec"></label>
            <button type="button" id="google-probe" class="button button-secondary">Periksa konektor</button>
        </div>
        <fieldset id="google-mapping-controls" class="form-stack" hidden><h3>Pemetaan kolom</h3><div id="google-mapping" class="column-mapping"></div><div id="google-sample" class="table-scroll"></div><p class="field-hint">Duplikasi mengikuti aturan di Persiapan. Edit operator yang bertabrakan ditandai; pemenang dan eliminasi tetap dilindungi.</p></fieldset>
        <label id="google-schedule-label" hidden>Tutup sinkronisasi otomatis<input id="google-closes" type="datetime-local"><span class="field-hint">Opsional. Setelah waktu ini, perubahan baru tidak dimasukkan.</span></label>
        <p id="google-status" class="field-hint" role="status"></p><p id="google-error" class="form-error" role="alert" hidden></p>
    </div>
    <div class="import-dialog-footer"><button type="button" id="google-connect" class="button button-save" hidden>Hubungkan</button></div>
</dialog>
<dialog id="google-issues-dialog" class="record-dialog import-dialog" aria-labelledby="google-issues-title">
    <div class="dialog-heading"><h2 id="google-issues-title">Periksa perubahan</h2><button type="button" id="google-issues-close" class="button button-quiet button-icon" aria-label="Tutup perubahan"><?= $icon('delete') ?></button></div>
    <div class="import-dialog-body"><p class="field-hint mb-3">Edit operator dipertahankan sampai Anda menentukan data yang dipakai. Isian tidak valid diperbaiki di Google Sheets.</p><div id="google-issues-table" class="table-scroll"></div><p id="google-issues-error" class="form-error mt-3" role="alert" hidden></p><div class="list-pagination"><button type="button" id="google-issues-previous" class="button button-secondary">Sebelumnya</button><span id="google-issues-page" class="field-hint"></span><button type="button" id="google-issues-next" class="button button-secondary">Berikutnya</button></div></div>
</dialog>
<dialog id="google-schedule-dialog" class="record-dialog" aria-labelledby="google-schedule-title"><form id="google-schedule-form" class="form-stack"><div class="dialog-heading"><h2 id="google-schedule-title">Waktu penutupan</h2><button type="button" id="google-schedule-close" class="button button-quiet button-icon" aria-label="Tutup waktu penutupan"><?= $icon('delete') ?></button></div><label>Tutup sinkronisasi<input type="datetime-local" id="google-schedule-time"><span class="field-hint">Kosongkan untuk tetap menerima pembaruan.</span></label><p id="google-schedule-error" class="form-error" role="alert" hidden></p><div class="dialog-actions"><button type="submit" class="button button-save" id="google-schedule-save">Simpan</button></div></form></dialog>
<template id="google-source-template"><div class="source-row"><div class="source-content"><div class="source-title"><a data-source-name target="_blank" rel="noopener noreferrer"></a><span data-source-phase class="quiet-badge"></span></div><p data-source-counts class="field-hint"></p><p data-source-message class="field-hint"></p></div><div class="source-actions"><button type="button" data-source-action="issues" class="button button-secondary" title="Periksa perubahan" aria-label="Periksa perubahan" hidden>! <span></span></button><button type="button" data-source-action="edit" class="button button-secondary button-icon" title="Jeda dan atur koneksi" aria-label="Jeda dan atur koneksi"><?= $icon('edit') ?></button><button type="button" data-source-action="schedule" class="button button-secondary button-icon" title="Waktu penutupan" aria-label="Waktu penutupan"><?= $icon('history') ?></button><button type="button" data-source-action="toggle" class="button button-secondary button-icon" title="Jeda sinkronisasi" aria-label="Jeda sinkronisasi"><?= $icon('play') ?></button><button type="button" data-source-action="disconnect" class="button button-secondary button-icon delete-action" title="Putuskan koneksi" aria-label="Putuskan koneksi"><?= $icon('remove') ?></button></div></div></template>
